static const char *ci_find(const char *haystack, const char *needle) {
    if (!haystack || !needle) return NULL;
    size_t needle_len = strlen(needle);
    if (needle_len == 0) return haystack;
    for (const char *p = haystack; *p; p++) {
        size_t i = 0;
        while (p[i] && needle[i] && tolower((unsigned char)p[i]) == tolower((unsigned char)needle[i])) {
            i++;
        }
        if (!needle[i]) return p;
    }
    return NULL;
}

static const char *find_tag(const char *html, const char *tag) {
    if (!html || !tag) return NULL;
    size_t tag_len = strlen(tag);
    const char *p = html;
    while ((p = ci_find(p, tag)) != NULL) {
        const char *after = p + tag_len;
        if (*after == '>' || isspace((unsigned char)*after)) {
            return p;
        }
        p = after;
    }
    return NULL;
}

static void trim(char *s) {
    if (!s) return;
    char *start = s;
    while (*start && isspace((unsigned char)*start)) start++;
    if (*start == '\0') {
        *s = '\0';
        return;
    }
    char *end = start;
    while (*end) end++;
    end--;
    while (end >= start && isspace((unsigned char)*end)) {
        *end = '\0';
        end--;
    }
    if (start != s) {
        memmove(s, start, strlen(start) + 1);
    }
}

